import{_ as n,o as e,c as s,aj as t}from"./chunks/framework.BdtAaXf2.js";const i="/assets/image-20241213060105633.6L1wDh_m.png",o="/assets/image-20241213060409063.CBF6HS2g.png",B="/assets/image-20241213060451980.FINdR1L3.png",r="/assets/image-20241213060631546.CB9d1znm.png",m="/assets/image-20241213061100309.7z5OwvnX.png",p="/assets/image-20241213061106489.DuoAsolU.png",g="/assets/image-20241213061112564.Hq28Ogwk.png",l="/assets/image-20241213061118990.BbZZZpde.png",E="/assets/image-20241213061139871.DSTCE66b.png",c="/assets/image-20241213061504092.DOCfbtPT.png",A="/assets/image-20241213061711657.D2i97Tof.png",d="/assets/image-20241213062004350.BpnUf1Iq.png",q=JSON.parse('{"title":"03-快速创建仓颉工程","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/03-快速创建仓颉工程/03-快速创建仓颉工程.md","filePath":"仓颉入门到实战/03-快速创建仓颉工程/03-快速创建仓颉工程.md","lastUpdated":1734063565000,"__rawMarkdown":"# 03-快速创建仓颉工程\\n\\n## 介绍\\n\\n仓颉工程有自身的一些目录结构和文件命名等限制，如果不安装规范来，那么在开发时，语法提示等插件将无效。编译打包时，也将可能\\n\\n出错。\\n\\n\\n\\n## 创建仓颉工程\\n\\n之前在vscode上安装好的仓颉插件，它内置了快速创建仓颉工程的功能。有两种方式可以创建\\n\\n### 可视化\\n\\n> 在 VSCode 中按 F1 或者 Ctrl + Shift + P（mac 上快捷键为 Command + Shift + P） 打开命令面板，然后按照以下步骤创建仓颉工程\\n\\n1. 输入关键字 **Create Cangjie ..**  找到创建新项目的菜单\\n\\n   ![image-20241213060105633](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213060105633.png)\\n\\n2. 输入工程信息\\n\\n   ![image-20241213060409063](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213060409063.png)\\n\\n3. 成功创建\\n\\n   ![image-20241213060451980](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213060451980.png)\\n\\n### vscode终端命令\\n\\n> 在 VSCode 中按 F1 或者 Ctrl + Shift + P（mac 上快捷键为 Command + Shift + P） 打开命令面板，然后按照以下步骤创建仓颉工程\\n\\n1. 选择创建工程命令 **cangjie:Create Cangjie Project**   *不要带 Project View 的*\\n\\n   ![image-20241213060631546](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213060631546.png)\\n\\n2. 选择编译引擎\\n\\n   ![image-20241213061100309](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061100309.png)\\n\\n3. 选择输出类型\\n\\n   ![image-20241213061106489](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061106489.png)\\n\\n4. 选择存放工程的目录\\n\\n   ![image-20241213061112564](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061112564.png)\\n\\n5. 输入项目的名称\\n\\n   ![image-20241213061118990](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061118990.png)\\n\\n6. 成功创建\\n\\n   ![image-20241213061139871](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061139871.png)\\n\\n   \\n\\n## 工程目录介绍\\n\\n![image-20241213061504092](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061504092.png)\\n\\n\\n\\n1. **.cache**  自动生成的缓存文件 \\n2. **.vscode**  自动生成的编辑器的设置文件 只在工作区有效\\n3. **src**  业务代码区域，我们在里面写代码，才能引入引入仓颉的一些内置类库、和代码提示\\n4. **cjpm.toml** 工程配置文件，记录和设置工程的相关信息\\n\\n\\n\\n## 代码提示\\n\\n在合法的工程中编写代码，便能享受到对应的代码提示\\n\\n![image-20241213061711657](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213061711657.png)\\n\\n\\n\\n## 编译工程\\n\\n快速编译工程\\n\\n![image-20241213062004350](03-%E5%BF%AB%E9%80%9F%E5%88%9B%E5%BB%BA%E4%BB%93%E9%A2%89%E5%B7%A5%E7%A8%8B.assets/image-20241213062004350.png)\\n\\n\\n\\n\\n\\n## 总结\\n\\n仓颉开发配件中较好的集成了创建工程、和运行工程相关的功能。我们只要按照标准规范操作，便可顺利开展我们变成的第一步！"}'),_={name:"仓颉入门到实战/03-快速创建仓颉工程/03-快速创建仓颉工程.md"};function h(F,a,f,u,C,P){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="_03-快速创建仓颉工程" tabindex="-1">03-快速创建仓颉工程 <a class="header-anchor" href="#_03-快速创建仓颉工程" aria-label="Permalink to &quot;03-快速创建仓颉工程&quot;">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><p>仓颉工程有自身的一些目录结构和文件命名等限制，如果不安装规范来，那么在开发时，语法提示等插件将无效。编译打包时，也将可能</p><p>出错。</p><h2 id="创建仓颉工程" tabindex="-1">创建仓颉工程 <a class="header-anchor" href="#创建仓颉工程" aria-label="Permalink to &quot;创建仓颉工程&quot;">​</a></h2><p>之前在vscode上安装好的仓颉插件，它内置了快速创建仓颉工程的功能。有两种方式可以创建</p><h3 id="可视化" tabindex="-1">可视化 <a class="header-anchor" href="#可视化" aria-label="Permalink to &quot;可视化&quot;">​</a></h3><blockquote><p>在 VSCode 中按 F1 或者 Ctrl + Shift + P（mac 上快捷键为 Command + Shift + P） 打开命令面板，然后按照以下步骤创建仓颉工程</p></blockquote><ol><li><p>输入关键字 <strong>Create Cangjie ..</strong> 找到创建新项目的菜单</p><p><img src="'+i+'" alt="image-20241213060105633"></p></li><li><p>输入工程信息</p><p><img src="'+o+'" alt="image-20241213060409063"></p></li><li><p>成功创建</p><p><img src="'+B+'" alt="image-20241213060451980"></p></li></ol><h3 id="vscode终端命令" tabindex="-1">vscode终端命令 <a class="header-anchor" href="#vscode终端命令" aria-label="Permalink to &quot;vscode终端命令&quot;">​</a></h3><blockquote><p>在 VSCode 中按 F1 或者 Ctrl + Shift + P（mac 上快捷键为 Command + Shift + P） 打开命令面板，然后按照以下步骤创建仓颉工程</p></blockquote><ol><li><p>选择创建工程命令 <strong>cangjie:Create Cangjie Project</strong> <em>不要带 Project View 的</em></p><p><img src="'+r+'" alt="image-20241213060631546"></p></li><li><p>选择编译引擎</p><p><img src="'+m+'" alt="image-20241213061100309"></p></li><li><p>选择输出类型</p><p><img src="'+p+'" alt="image-20241213061106489"></p></li><li><p>选择存放工程的目录</p><p><img src="'+g+'" alt="image-20241213061112564"></p></li><li><p>输入项目的名称</p><p><img src="'+l+'" alt="image-20241213061118990"></p></li><li><p>成功创建</p><p><img src="'+E+'" alt="image-20241213061139871"></p></li></ol><h2 id="工程目录介绍" tabindex="-1">工程目录介绍 <a class="header-anchor" href="#工程目录介绍" aria-label="Permalink to &quot;工程目录介绍&quot;">​</a></h2><p><img src="'+c+'" alt="image-20241213061504092"></p><ol><li><strong>.cache</strong> 自动生成的缓存文件</li><li><strong>.vscode</strong> 自动生成的编辑器的设置文件 只在工作区有效</li><li><strong>src</strong> 业务代码区域，我们在里面写代码，才能引入引入仓颉的一些内置类库、和代码提示</li><li><strong>cjpm.toml</strong> 工程配置文件，记录和设置工程的相关信息</li></ol><h2 id="代码提示" tabindex="-1">代码提示 <a class="header-anchor" href="#代码提示" aria-label="Permalink to &quot;代码提示&quot;">​</a></h2><p>在合法的工程中编写代码，便能享受到对应的代码提示</p><p><img src="'+A+'" alt="image-20241213061711657"></p><h2 id="编译工程" tabindex="-1">编译工程 <a class="header-anchor" href="#编译工程" aria-label="Permalink to &quot;编译工程&quot;">​</a></h2><p>快速编译工程</p><p><img src="'+d+'" alt="image-20241213062004350"></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>仓颉开发配件中较好的集成了创建工程、和运行工程相关的功能。我们只要按照标准规范操作，便可顺利开展我们变成的第一步！</p>',23)])])}const S=n(_,[["render",h]]);export{q as __pageData,S as default};
